/* Kick Theme - Official Kick brand colors */

/* Light mode */
[data-theme="kick-light"] {
  --background: rgb(255, 255, 255);
  --foreground: rgb(6, 6, 6);
  --card: rgb(248, 248, 248);
  --card-foreground: rgb(6, 6, 6);
  --popover: rgb(255, 255, 255);
  --popover-foreground: rgb(6, 6, 6);
  --primary: rgb(137, 195, 0);
  --primary-foreground: rgb(6, 6, 6);
  --secondary: rgb(240, 238, 238);
  --secondary-foreground: rgb(22, 22, 22);
  --muted: rgb(242, 242, 242);
  --muted-foreground: rgb(99, 99, 99);
  --accent: rgb(150, 213, 0);
  --accent-foreground: rgb(6, 6, 6);
  --destructive: rgb(212, 9, 36);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(222, 222, 222);
  --input: rgb(228, 228, 228);
  --ring: rgb(137, 195, 0);
  --chart-1: rgb(137, 195, 0);
  --chart-2: rgb(0, 166, 146);
  --chart-3: rgb(0, 176, 213);
  --chart-4: rgb(113, 115, 215);
  --chart-5: rgb(183, 48, 149);
  --radius: 0.625rem;
  --sidebar: rgb(248, 248, 248);
  --sidebar-foreground: rgb(6, 6, 6);
  --sidebar-primary: rgb(137, 195, 0);
  --sidebar-primary-foreground: rgb(6, 6, 6);
  --sidebar-accent: rgb(240, 238, 238);
  --sidebar-accent-foreground: rgb(22, 22, 22);
  --sidebar-border: rgb(222, 222, 222);
  --sidebar-ring: rgb(137, 195, 0);
  --font-sans: Inter, ui-sans-serif, system-ui, sans-serif;
  --font-serif: ui-serif, Georgia, serif;
  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", monospace;
  --shadow-color: rgb(8, 69, 18);
  --shadow-opacity: 0.08;
  --shadow-blur: 4px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 2px;
  --letter-spacing: -0.01em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 2px 0px hsl(130 80% 15% / 0.04);
  --shadow-xs: 0 1px 3px 0px hsl(130 80% 15% / 0.06);
  --shadow-sm:
    0 2px 4px 0px hsl(130 80% 15% / 0.08),
    0 1px 2px -1px hsl(130 80% 15% / 0.08);
  --shadow:
    0 2px 4px 0px hsl(130 80% 15% / 0.08),
    0 1px 2px -1px hsl(130 80% 15% / 0.08);
  --shadow-md:
    0 4px 6px 0px hsl(130 80% 15% / 0.1), 0 2px 4px -1px hsl(130 80% 15% / 0.1);
  --shadow-lg:
    0 8px 10px 0px hsl(130 80% 15% / 0.1), 0 4px 6px -1px hsl(130 80% 15% / 0.1);
  --shadow-xl:
    0 16px 20px 0px hsl(130 80% 15% / 0.12),
    0 8px 10px -1px hsl(130 80% 15% / 0.12);
  --shadow-2xl: 0 24px 48px 0px hsl(130 80% 15% / 0.2);
  --tracking-normal: -0.01em;
}

/* Dark mode - #0D0D0D is Kick's signature black background */
[data-theme="kick-dark"] {
  --background: rgb(6, 6, 6);
  --foreground: rgb(255, 255, 255);
  --card: rgb(10, 11, 12);
  --card-foreground: rgb(255, 255, 255);
  --popover: rgb(14, 16, 18);
  --popover-foreground: rgb(255, 255, 255);
  --primary: rgb(163, 231, 0);
  --primary-foreground: rgb(6, 6, 6);
  --secondary: rgb(21, 22, 23);
  --secondary-foreground: rgb(222, 222, 222);
  --muted: rgb(17, 18, 19);
  --muted-foreground: rgb(128, 128, 128);
  --accent: rgb(163, 231, 0);
  --accent-foreground: rgb(6, 6, 6);
  --destructive: rgb(222, 59, 61);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(34, 36, 38);
  --input: rgb(21, 22, 23);
  --ring: rgb(163, 231, 0);
  --chart-1: rgb(163, 231, 0);
  --chart-2: rgb(0, 184, 161);
  --chart-3: rgb(0, 193, 233);
  --chart-4: rgb(128, 131, 226);
  --chart-5: rgb(194, 75, 161);
  --radius: 0.625rem;
  --sidebar: rgb(3, 3, 3);
  --sidebar-foreground: rgb(255, 255, 255);
  --sidebar-primary: rgb(163, 231, 0);
  --sidebar-primary-foreground: rgb(6, 6, 6);
  --sidebar-accent: rgb(21, 22, 23);
  --sidebar-accent-foreground: rgb(222, 222, 222);
  --sidebar-border: rgb(34, 36, 38);
  --sidebar-ring: rgb(163, 231, 0);
  --font-sans: Inter, ui-sans-serif, system-ui, sans-serif;
  --font-serif: ui-serif, Georgia, serif;
  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.5;
  --shadow-blur: 4px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 2px;
  --letter-spacing: -0.01em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 2px 0px hsl(0 0% 0% / 0.25);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.35);
  --shadow-sm:
    0 2px 4px 0px hsl(0 0% 0% / 0.5), 0 1px 2px -1px hsl(0 0% 0% / 0.5);
  --shadow: 0 2px 4px 0px hsl(0 0% 0% / 0.5), 0 1px 2px -1px hsl(0 0% 0% / 0.5);
  --shadow-md:
    0 4px 6px 0px hsl(0 0% 0% / 0.5), 0 2px 4px -1px hsl(0 0% 0% / 0.5);
  --shadow-lg:
    0 8px 10px 0px hsl(0 0% 0% / 0.5), 0 4px 6px -1px hsl(0 0% 0% / 0.5);
  --shadow-xl:
    0 16px 20px 0px hsl(0 0% 0% / 0.5), 0 8px 10px -1px hsl(0 0% 0% / 0.5);
  --shadow-2xl: 0 24px 48px 0px hsl(0 0% 0% / 0.6);
}
